#!/usr/bin/env node
// Keeps every generated agent entry point and reference in step with the
// canonical sources:
//   system/skills/taptop-site-transfer/  → .claude/skills/… (Claude Code)
//                                        → .agents/skills/… (Codex)
//   system/lib/cli-usage.js              → system/docs/cli-reference.md
//   AGENTS.md                            ← CLAUDE.md imports it
// `--check` writes nothing and fails when a generated file is stale.
const fs = require('node:fs');
const path = require('node:path');
const { COMMANDS } = require('../lib/cli-usage');

const ROOT = path.resolve(__dirname, '../..');
const SKILL = 'system/skills/taptop-site-transfer';
const ADAPTERS = ['.claude/skills/taptop-site-transfer', '.agents/skills/taptop-site-transfer'];
const NOTE = '<!-- Generated by `npm run docs:sync` from system/skills/taptop-site-transfer/. Edit the source there, never this copy. -->';

function rewriteLinks(markdown, fromDir) {
  // Links in the canonical skill are relative to it; make them relative to the adapter.
  return markdown.replace(/\]\((?!https?:|#)([^)\s]+)\)/g, (match, href) => {
    const target = path.posix.normalize(path.posix.join(SKILL, href));
    return `](${path.posix.relative(fromDir, target)})`;
  });
}

function adapterText(source, dir) {
  const match = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(source);
  if (!match) throw new Error('SKILL_FRONTMATTER_MISSING');
  const body = rewriteLinks(match[2], dir).replace(/^\n+/, '');
  return `---\n${match[1]}\n---\n${NOTE}\n\n${body}`;
}

function cliReference() {
  const row = item => `| \`${item.name}\` | \`npm run toolkit -- ${item.synopsis}\` | ${item.purpose} |`;
  return [
    '# CLI reference',
    '',
    '<!-- Generated by `npm run docs:sync` from system/lib/cli-usage.js. Do not edit by hand. -->',
    '',
    'Run every command from the Toolkit folder. Commands that change a project take it explicitly; none of them keeps a global active project.',
    '',
    '| Command | Synopsis | Purpose |',
    '| --- | --- | --- |',
    ...COMMANDS.filter(item => !item.legacy).map(row),
    '',
    '## Single-page and support commands',
    '',
    '| Command | Synopsis | Purpose |',
    '| --- | --- | --- |',
    ...COMMANDS.filter(item => item.legacy).map(row),
    ''
  ].join('\n');
}

const CLAUDE = `@AGENTS.md\n\n<!-- Claude Code reads this file; the shared instructions for every agent live in AGENTS.md (imported above). The Toolkit skill is in .claude/skills/taptop-site-transfer/, generated from system/skills/taptop-site-transfer/. -->\n`;

function expectedFiles(root = ROOT) {
  const files = new Map();
  const source = fs.readFileSync(path.join(root, SKILL, 'SKILL.md'), 'utf8');
  for (const dir of ADAPTERS) files.set(`${dir}/SKILL.md`, adapterText(source, dir));
  files.set('system/docs/cli-reference.md', cliReference());
  files.set('CLAUDE.md', CLAUDE);
  return files;
}

function syncAgentDocs({ root = ROOT, check = false } = {}) {
  const stale = [];
  for (const [file, text] of expectedFiles(root)) {
    const target = path.join(root, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (current === text) continue;
    stale.push(file);
    if (!check) {
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.writeFileSync(target, text);
    }
  }
  return { stale, written: check ? [] : stale };
}

if (require.main === module) {
  const check = process.argv.includes('--check');
  const result = syncAgentDocs({ check });
  if (check && result.stale.length) {
    console.error(`Generated agent docs are out of date: ${result.stale.join(', ')}\nRun: npm run docs:sync`);
    process.exitCode = 1;
  } else console.log(check ? 'Generated agent docs are up to date.' : `Updated: ${result.written.join(', ') || 'nothing'}`);
}

module.exports = { syncAgentDocs, expectedFiles, ADAPTERS, SKILL };
